30:   const displayName = WrappedComponent.displayName || WrappedComponent.name || 'Component';
31: 
32:   const ComponentWithUserDetail = (props: T) => {
33:     const { partyId, userId, productId } = useParams<UserUrlParams>();
34:     const fetchUserDetail = useUserDetail();
35:     const [partyUser, setPartyUser] = useState<PartyUserDetail | null>();
36:     const addError = useErrorDispatcher();
37:     const history = useHistory();
38:     const { getAllProductsWithPermission } = usePermissions();
39:     const canSeeUsers =
40:       getAllProductsWithPermission(Actions.ListProductUsers).length > 0 ||
41:       getAllProductsWithPermission(Actions.ListAllProductUsers).length > 0;
42: 
43:     const doFetch = () => {
44:       fetchUserDetail(partyId, userId, props.productsMap)
45:         .then((user) => {
46:           if (user === null) {
47:             const goBackUrl = productId
48:               ? resolvePathVariables(DASHBOARD_USERS_ROUTES.PARTY_PRODUCT_USERS.path, {
49:                   partyId,
