51:                 })
52:               : resolvePathVariables(DASHBOARD_USERS_ROUTES.PARTY_USERS.path, {
53:                   partyId,
54:                 });
55: 
56:             addError({
57:               id: 'INVALID_PARTY_USER_ID_' + userId + '__' + partyId,
58:               blocking: false,
59:               techDescription: `Selected an invalid user Id ${userId} and/or institution id ${partyId}`,
60:               toNotify: false,
61:               error: new Error('INVALID_PARTY_USER_ID_INSTITUTION_ID'),
62:               onClose: () => history.push(goBackUrl),
63:               displayableDescription: "Impossibile trovare l'utente selezionato",
64:             });
