66:           setPartyUser(user);
67:         })
68:         .catch((reason) => {
69:           addError({
70:             id: uniqueId(`${ComponentWithUserDetail.displayName}-`),
71:             blocking: false,
72:             error: reason,
73:             techDescription: `An error occurred while fetching user detail in component ${ComponentWithUserDetail.displayName}`,
74:             onRetry: doFetch,
75:             toNotify: true,
76:           });
77:         });
78:     };
79: 
80:     useEffect(() => {
81:       if (!canSeeUsers) {
82:         history.push(resolvePathVariables(ENV.ROUTES.OVERVIEW, { partyId }));
83:       } else if (partyId && userId) {
84:         doFetch();
85:       } else {
